"""Hidden behavioral tests for cmark: input_bytes. Generated by pbkit from the gold binary."""


def test_crlf(run):
    r = run(args=[], stdin=b'# t\r\n\r\npara\r\nline\r\n')
    assert r.stdout == b'<h1>t</h1>\n<p>para\nline</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_crlf_validate(run):
    r = run(args=['--validate-utf8'], stdin=b'# t\r\n\r\npara\r\nline\r\n')
    assert r.stdout == b'<h1>t</h1>\n<p>para\nline</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_crlf_xml(run):
    r = run(args=['-t', 'xml', '--validate-utf8'], stdin=b'# t\r\n\r\npara\r\nline\r\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document xmlns="http://commonmark.org/xml/1.0">\n  <heading level="1">\n    <text xml:space="preserve">t</text>\n  </heading>\n  <paragraph>\n    <text xml:space="preserve">para</text>\n    <softbreak />\n    <text xml:space="preserve">line</text>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_crlf_commonmark(run):
    r = run(args=['-t', 'commonmark'], stdin=b'# t\r\n\r\npara\r\nline\r\n')
    assert r.stdout == b'# t\n\npara\nline\n'
    assert r.stderr == b''
    assert r.returncode == 0


